defense.vulnerable_config:
# Dangerous ACE — HelpDesk has GenericAll on a DA account:
Get-ObjectAcl 'DomainAdmin1' -ResolveGUIDs | Where-Object {$_.ActiveDirectoryRights -match 'GenericAll'}
# Output: CORP\HelpDesk — GenericAll → can reset DA password

# WriteDACL on domain object:
Get-ObjectAcl 'DC=corp,DC=local' -ResolveGUIDs | Where-Object {$_.ActiveDirectoryRights -match 'WriteDacl'}
